// SPDX-License-Identifier: LicenseRef-PolyForm-Perimeter-1.0.1
pragma solidity ^0.8.28;

import { IRoycoVaultTranche } from "./IRoycoVaultTranche.sol";

/**
 * @title IRoycoSeniorTranche
 * @notice Interface for the senior tranche (ST): the standard share-token surface (inherited from IRoycoVaultTranche) plus
 *         the senior-specific liquidity premium share mint, by which the kernel routes senior yield to the liquidity provider tranche
 *         as newly minted senior shares
 * @dev Only the senior tranche carries this mint: the liquidity premium is a reassignment of senior appreciation, so it is
 *      paid as senior shares
 *      The junior and liquidity provider tranches share the base IRoycoVaultTranche surface without it
 */
interface IRoycoSeniorTranche is IRoycoVaultTranche {
    /**
     * @notice Emitted when liquidity premium shares are minted to the kernel on behalf of the liquidity provider tranche
     * @param holder The address that received the minted premium shares (the kernel, which custodies them for the liquidity provider tranche)
     * @param mintedLiquidityPremiumShares The number of senior shares minted as the liquidity premium
     * @param totalTrancheShares The total shares in the senior tranche after minting the liquidity premium shares
     */
    event LiquidityPremiumSharesMinted(address indexed holder, uint256 mintedLiquidityPremiumShares, uint256 totalTrancheShares);

    /**
     * @notice Mints a kernel-computed number of liquidity premium shares to the kernel
     * @dev Only callable by the kernel during accounting synchronization
     * @dev The premium shares always land in the kernel, which custodies them for the liquidity provider tranche
     * @dev The liquidity premium is senior yield routed to the liquidity provider tranche, minted as senior tranche shares held by
     *      the kernel on the LPT's behalf, this leaves the collateral NAV (and thus coverage) unchanged, so the mint is
     *      coverage-neutral and only reassigns senior appreciation to the LPT
     * @dev Takes a precomputed share count, priced jointly with the ST protocol fee so neither carve-out dilutes the other
     * @param _liquidityPremiumShares The precomputed number of liquidity premium shares to mint
     * @return totalTrancheShares The total shares in the senior tranche after minting the liquidity premium shares
     */
    function mintLiquidityPremiumShares(uint256 _liquidityPremiumShares) external returns (uint256 totalTrancheShares);
}

src/interfaces/IRoycoVaultTranche.sol.content:
// SPDX-License-Identifier: LicenseRef-PolyForm-Perimeter-1.0.1
pragma solidity ^0.8.28;

import { IERC20Metadata } from "../../lib/openzeppelin-contracts/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { AssetClaims, TrancheType } from "../libraries/Types.sol";
import { TRANCHE_UNIT } from "../libraries/Units.sol";

/**
 * @title IRoycoVaultTranche
 * @notice Interface for the Royco vault tranche contract that manages LP deposits and redemptions for a given tranche
 * @dev Extends ERC20 with vault-like deposit/redeem functionality and protocol fee share minting
 */
interface IRoycoVaultTranche is IERC20Metadata {
    /**
     * @custom:field name - The name of the tranche share token (should be prefixed with "Royco-ST", "Royco-JT", or "Royco-LPT")
     * @custom:field symbol - The symbol of the tranche share token (should be prefixed with "ST", "JT", or "LPT")
     * @custom:field initialAuthority - The initial authority for the tranche
     * @custom:field kernel - The kernel that handles the core market logic and accounting synchronization
     * @custom:field asset - The underlying yield bearing asset of the tranche
     */
    struct RoycoTrancheInitParams {
        string name;
        string symbol;
        address initialAuthority;
        address kernel;
        address asset;
    }

    /**
     * @notice Storage state for the Royco vault tranche
     * @custom:storage-location erc7201:Royco.storage.RoycoVaultTrancheState
     * @custom:field kernel - The kernel that handles the core market logic and accounting synchronization
     * @custom:field asset - The address of the yield bearing asset of the tranche
     */
    struct RoycoVaultTrancheState {
        address kernel;
        address asset;
    }

    /**
     * @notice Emitted when a deposit is made into the tranche
     * @param sender The address that initiated the deposit
     * @param receiver The address that received the minted shares
     * @param assets The amount of assets deposited, denominated in the tranche's base asset units
     * @param shares The amount of shares minted to the receiver
     */
    event Deposit(address indexed sender, address indexed receiver, TRANCHE_UNIT assets, uint256 shares);

    /**
     * @notice Emitted when a redemption is made from the tranche
     * @param sender The address that initiated the redemption
     * @param receiver The address that received the redeemed assets
     * @param claims The asset claims received by the receiver, including claims on the collateral assets, LPT assets, ST shares, and their total NAV value
     * @param shares The amount of shares redeemed
     */
    event Redeem(address indexed sender, address indexed receiver, AssetClaims claims, uint256 shares);

    /**
     * @notice Emitted when protocol fee shares are minted to the fee recipient
     * @param protocolFeeRecipient The address that received the minted protocol fee shares
     * @param mintedProtocolFeeShares The number of protocol fee shares minted
     * @param totalTrancheShares The total shares in the tranche after minting the protocol fee shares
     */
    event ProtocolFeeSharesMinted(address indexed protocolFeeRecipient, uint256 mintedProtocolFeeShares, uint256 totalTrancheShares);

    /// @notice Thrown when the caller of a permissioned function is not the tranche's configured kernel
    error ONLY_KERNEL();

    /// @notice Returns the address of the kernel that this tranche is associated with
    /// @return kernel The address of the kernel responsible for executing deposits and redemptions for this tranche
    function kernel() external view returns (address kernel);

    /**
     * @notice Deposits assets into the tranche and mints shares to the receiver
     * @dev Transfers assets from the caller and mints shares to the receiver
     * @param _assets The amount of assets to deposit, denominated in the tranche's base asset units
     * @param _receiver The address that will receive the minted shares
     * @return shares The number of shares minted to the receiver
     */
    function deposit(TRANCHE_UNIT _assets, address _receiver) external returns (uint256 shares);

    /**
     * @notice Redeems shares from the tranche and transfers assets to the receiver
     * @dev Burns shares from the owner and transfers the corresponding asset claims to the receiver
     * @param _shares The number of shares to redeem
     * @param _receiver The address that will receive the redeemed assets
     * @param _owner The address that owns the shares being redeemed
     * @return claims The asset claims transferred to the receiver, including claims on the collateral assets, LPT assets, ST shares, and their total NAV value
     */
    function redeem(uint256 _shares, address _receiver, address _owner) external returns (AssetClaims memory claims);

    /**
     * @notice Mints a kernel-computed number of protocol fee shares to the specified fee recipient
     * @dev Only callable by the kernel during accounting synchronization
     * @dev Takes a precomputed share count rather than a NAV: the kernel prices every tranche's protocol fee shares (and the
     *      senior liquidity premium) against the post-carve-out NAV so neither dilutes the other and the tranche only mints the count
     * @param _protocolFeeRecipient The address that will receive the minted protocol fee shares
     * @param _protocolFeeShares The precomputed number of protocol fee shares to mint
     * @return totalTrancheShares The total shares in the tranche after minting the protocol fee shares
     */
    function mintProtocolFeeShares(address _protocolFeeRecipient, uint256 _protocolFeeShares) external returns (uint256 totalTrancheShares);

    /**
     * @notice Mints tranche shares to the specified account
     * @dev Only callable by the kernel, which prices every mint inside a synchronized operation
     * @dev Takes a raw share count: the caller (kernel) is responsible for computing a fair, non-diluting amount
     * @param _to The account to mint the shares to
     * @param _shares The number of shares to mint
     */
    function kernelMint(address _to, uint256 _shares) external;

    /**
     * @notice Burns the specified number of tranche shares from the specified owner
     * @dev Only callable by the kernel during a redemption flow, after the owner's claims have been scaled against the pre-burn supply
     * @dev Takes a raw share count: redemption inputs are validated upstream by the tranche, so a derived zero share burn is a permitted no-op
     * @param _from The address whose tranche shares are burned
     * @param _shares The number of tranche shares to burn
     */
    function kernelBurn(address _from, uint256 _shares) external;

    /**
     * @notice Previews the number of shares that would be minted for a given deposit amount
     * @dev NON-VIEW: routes the deposit through its execute-and-revert simulation, which mutates no state net
     * @dev The quote is produced by the actual kernel deposit path, so any revert the deposit would raise bubbles unchanged
     * @param _assets The amount of assets to deposit, denominated in the tranche's base asset units
     * @return shares The number of shares that would be minted for the specified deposit amount
     */
    function previewDeposit(TRANCHE_UNIT _assets) external returns (uint256 shares);

    /**
     * @notice Previews the asset claims that would be received for a given redemption amount
     * @dev NON-VIEW: routes the redemption through its execute-and-revert simulation, which mutates no state net
     * @dev The quote is produced by the actual kernel redemption path, so any revert the redemption would raise bubbles unchanged
     * @param _shares The number of shares to redeem
     * @return claims The asset claims that would be received, including claims on the collateral assets, LPT assets, ST shares, and their total NAV value
     */
    function previewRedeem(uint256 _shares) external returns (AssetClaims memory claims);

    /**
     * @notice Converts a specified number of shares to asset claims using the current exchange rate
     * @dev Does not mutate any state
     * @dev For the liquidity provider tranche this is the composability-facing exchange rate and is LPT-asset-only (the raw NAV,
     *      `stShares` always zero): the claimable idle liquidity-premium senior shares are excluded, so the quoted
     *      price is a conservative floor that cannot dip when a staged premium deploys into the pool
     *      Use `previewRedeem` for the accurate redemption quote, which includes the idle slice paid in-kind, the two
     *      coincide exactly when no premium is staged
     * @param _shares The number of shares to convert
     * @return claims The equivalent asset claims for the specified share amount, including claims on the collateral assets, LPT assets, ST shares, and their total NAV value
     */
    function convertToAssets(uint256 _shares) external view returns (AssetClaims memory claims);

    /**
     * @notice Converts a specified amount of assets to shares using the current exchange rate
     * @dev Does not mutate any state
     * @dev For the liquidity provider tranche the exchange rate is LPT-asset-only (the raw NAV): the claimable idle
     *      liquidity-premium senior shares are excluded, so the quoted rate cannot dip when a staged premium deploys
     *      Use `previewDeposit` for the accurate deposit quote, which prices at the idle-inclusive effective NAV
     * @param _assets The amount of assets to convert, denominated in the tranche's base asset units
     * @return shares The equivalent number of shares for the specified asset amount
     */
    function convertToShares(TRANCHE_UNIT _assets) external view returns (uint256 shares);

    /**
     * @notice Returns the maximum amount of assets that can be deposited by the specified receiver
     * @dev May return zero if deposits are disabled due to market conditions (e.g., ST impermanent loss exists or coverage violated)
     * @param _receiver The address that would receive the minted shares
     * @return assets The maximum amount of assets that can be deposited, denominated in the tranche's base asset units
     */
    function maxDeposit(address _receiver) external view returns (TRANCHE_UNIT assets);

    /**
     * @notice Returns the maximum number of shares that can be redeemed by the specified owner
     * @dev May return zero if redemptions are disabled due to market conditions (e.g., fixed-term state for ST)
     * @param _owner The address that owns the shares to be redeemed
     * @return shares The maximum number of shares that can be redeemed
     */
    function maxRedeem(address _owner) external view returns (uint256 shares);

    /**
     * @notice Returns the total effective assets held by this tranche
     * @dev The effective assets include the claims on the collateral assets after accounting for coverage and yield sharing
     * @return claims The total asset claims held by this tranche, including claims on the collateral assets, LPT assets, ST shares, and their total NAV value
     */
    function totalAssets() external view returns (AssetClaims memory claims);

    /// @notice Returns the address of the underlying base asset for this tranche
    /// @return asset The address of the ERC20 token used as the base asset for deposits into this tranche
    function asset() external view returns (address asset);

    /// @notice Returns the tranche type indicating whether this is a senior, junior, or liquidity provider tranche
    /// @return trancheType An enumerator indicating SENIOR, JUNIOR, or LIQUIDITY tranche type
    function TRANCHE_TYPE() external view returns (TrancheType trancheType);
}

src/libraries/Types.sol.content:
// SPDX-License-Identifier: LicenseRef-PolyForm-Perimeter-1.0.1
pragma solidity ^0.8.28;

import { NAV_UNIT, TRANCHE_UNIT } from "./Units.sol";

/**
 * @title MarketState
 * @notice Defines the operational state of a Royco market
 * @custom:state PERPETUAL
 *      Normal operating state where market forces govern behavior, and the permanent state of a market configured with no fixed-term duration
 *      - The market is healthy (no losses over dust tolerance), severely undercollateralized (liquidation coverage utilization breached), or uncollateralized (no JT NAV remaining against a non-zero ST NAV)
 *      - All three tranches are liquid, subject to the coverage and liquidity requirements at all times, including while under or uncollateralized
 *      - Premiums and protocol fees accrue on ST yield, and adaptive curve YDMs adapt to this market's coverage and liquidity utilization
 * @custom:state FIXED_TERM
 *      Temporary recovery state entered when JT covers an ST drawdown while coverage stays within the liquidation threshold
 *      - Entered when a non-dust JT impermanent loss is first incurred
 *      - ST deposits and redemptions blocked: stops ST withdrawing coverage from existing JT on arbitrary volatility
 *      - JT deposits and redemptions blocked: stops new JT diluting existing JT on arbitrary volatility
 *      - LPT redemptions blocked: keeps the LPT market making the ST when secondary liquidity is most valuable
 *      - No liquidity premium is paid and no protocol fees are taken, since there is no yield to distribute during recovery
 *      - Adaptive curve YDMs do not adapt, since utilization moves on underlying PNL rather than market forces during recovery
 *      - Transitions back to PERPETUAL when the JT impermanent loss clears or the term elapses, and is forced back on a liquidation breach or an uncollateralized market, clearing the JT impermanent loss
 */
enum MarketState {
    PERPETUAL,
    FIXED_TERM
}

/**
 * @title DispatchMode
 * @dev Defines how a dispatched operation runs
 * @custom:type SIMULATE - Computes the operation's result under real execution semantics, then unwinds every mutation by reverting with the ABI encoded result
 * @custom:type EXECUTE - Executes and settles the operation
 */
enum DispatchMode {
    SIMULATE,
    EXECUTE
}

/**
 * @title AssetClaims
 * @dev A struct representing claims on collateral assets, liquidity provider tranche assets, senior tranche shares, and NAV
 * @custom:field collateralAssets - The claim on the coinvested collateral assets denominated in tranche units (only applicable for the ST and JT)
 * @custom:field lptAssets - The claim on liquidity provider tranche assets denominated in LPT's tranche units (only applicable for the LPT)
 * @custom:field stShares - The claim on senior tranche shares (only applicable for the LPT)
 * @custom:field nav - The net asset value of these claims in NAV units
 */
struct AssetClaims {
    // ST and JT claims
    TRANCHE_UNIT collateralAssets;
    // LPT claims
    TRANCHE_UNIT lptAssets;
    uint256 stShares;
    // Total net asset value of the claims
    NAV_UNIT nav;
}

/**
 * @title SyncedAccountingState
 * @dev Contains all current mark-to-market NAV accounting data for the market's tranches
 * @custom:field marketState - The current state of the Royco market (perpetual or fixed term)
 * @custom:field collateralNAV - The pure value of the coinvested collateral backing the senior and junior tranches, always equal to (stEffectiveNAV + jtEffectiveNAV)
 * @custom:field lptRawNAV - The liquidity provider tranche's current raw NAV: the mark-to-market value of its market making inventory
 * @custom:field stEffectiveNAV - Senior tranche effective NAV: its claim on the collateral, includes applied coverage, its share of ST yield, and uncovered losses
 * @custom:field jtEffectiveNAV - Junior tranche effective NAV: its claim on the collateral, includes provided coverage, JT yield, its share of ST yield, and JT losses
 * @custom:field jtImpermanentLoss - The junior tranche's impermanent loss: JT's recoverable drawdown, deepened by JT losses and provided coverage, repaid by JT's first claim on appreciation/recovery
 * @custom:field lptLiquidityPremium - The liquidity premium accrued to the liquidity provider tranche on this sync: LPT's share of senior yield, minted as senior tranche shares to LPT (coverage-neutral)
 * @custom:field stProtocolFee - Protocol fee taken on ST yield on this sync
 * @custom:field jtProtocolFee - Protocol fee taken on JT yield on this sync
 * @custom:field lptProtocolFee - Protocol fee taken on the liquidity premium (LPT yield share) on this sync
 * @custom:field coverageUtilizationWAD - The current coverageUtilization of the market, scaled to WAD precision
 * @custom:field liquidityUtilizationWAD - The current liquidityUtilization of the market, scaled to WAD precision
 * @custom:field fixedTermEndTimestamp - The timestamp at which the fixed term ends, set to 0 if the market is not in a fixed term state
 * @custom:field minCoverageWAD - The coverage percentage that the senior tranche is expected to be protected by, scaled to WAD precision
 * @custom:field coverageLiquidationUtilizationWAD - The liquidation coverageUtilization threshold for this market, scaled to WAD precision
 * @custom:field minLiquidityWAD - The percentage of the senior tranche NAV that must be in the liquidity provider tranche's market making inventory, scaled to WAD precision
 */
struct SyncedAccountingState {
    // The market's current operating state (PERPETUAL or FIXED_TERM)
    MarketState marketState;
    // The market's marked-to-market NAVs, JT impermanent loss, LPT liquidity premium, and fees
    NAV_UNIT collateralNAV;
    NAV_UNIT lptRawNAV;
    NAV_UNIT stEffectiveNAV;
    NAV_UNIT jtEffectiveNAV;
    NAV_UNIT jtImpermanentLoss;
    NAV_UNIT lptLiquidityPremium;
    NAV_UNIT stProtocolFee;
    NAV_UNIT jtProtocolFee;
    NAV_UNIT lptProtocolFee;
    // The market's derived state metrics
    uint256 coverageUtilizationWAD;
    uint256 liquidityUtilizationWAD;
    uint32 fixedTermEndTimestamp;
    // The market's coverage configuration
    uint256 minCoverageWAD;
    uint256 coverageLiquidationUtilizationWAD;
    // The market's liquidity configuration
    uint256 minLiquidityWAD;
}

/**
 * @title Operation
 * @dev Defines the type of operation being executed by the user
 * @custom:type ST_DEPOSIT - A senior tranche deposit that increases ST's effective NAV
 * @custom:type ST_REDEMPTION - A senior tranche redemption that decreases ST's effective NAV
 * @custom:type JT_DEPOSIT - A junior tranche deposit that increases JT's effective NAV
 * @custom:type JT_REDEMPTION - A junior tranche redemption that decreases JT's effective NAV
 * @custom:type LPT_DEPOSIT - An in-kind liquidity provider tranche deposit that only adds market-making inventory
 * @custom:type LPT_REDEMPTION - An in-kind liquidity provider tranche redemption that only removes market-making inventory and idle premium shares
 */
enum Operation {
    ST_DEPOSIT,
    ST_REDEMPTION,
    JT_DEPOSIT,
    JT_REDEMPTION,
    LPT_DEPOSIT,
    LPT_REDEMPTION
}

/**
 * @title TrancheType
 * @dev Defines the types of Royco tranches deployed per market
 * @custom:type SENIOR - The identifier for the senior tranche (protected capital)
 * @custom:type JUNIOR - The identifier for the junior tranche (first-loss capital)
 * @custom:type LIQUIDITY_PROVIDER - The identifier for the liquidity provider tranche (senior's market-making capital)
 */
enum TrancheType {
    SENIOR,
    JUNIOR,
    LIQUIDITY_PROVIDER
}

/**
 * @notice Maps the specified tranche to its deposit operation
 * @param _trancheType The tranche to return the deposit operation for
 * @return The deposit operation committed by the specified tranche's in-kind deposit
 */
function toDepositOperation(TrancheType _trancheType) pure returns (Operation) {
    if (_trancheType == TrancheType.SENIOR) return Operation.ST_DEPOSIT;
    else if (_trancheType == TrancheType.JUNIOR) return Operation.JT_DEPOSIT;
    else return Operation.LPT_DEPOSIT;
}

/**
 * @notice Maps the specified tranche to its redemption operation
 * @param _trancheType The tranche to return the redemption operation for
 * @return The redemption operation committed by the specified tranche's in-kind redemption
 */
function toRedemptionOperation(TrancheType _trancheType) pure returns (Operation) {
    if (_trancheType == TrancheType.SENIOR) return Operation.ST_REDEMPTION;
    else if (_trancheType == TrancheType.JUNIOR) return Operation.JT_REDEMPTION;
    else return Operation.LPT_REDEMPTION;
}

src/tranches/base/RoycoVaultTranche.sol.content:
// SPDX-License-Identifier: LicenseRef-PolyForm-Perimeter-1.0.1
pragma solidity ^0.8.28;

import { ERC20Upgradeable, IERC20, IERC20Metadata } from "../../../lib/openzeppelin-contracts-upgradeable/contracts/token/ERC20/ERC20Upgradeable.sol";
import { ERC20BurnableUpgradeable } from "../../../lib/openzeppelin-contracts-upgradeable/contracts/token/ERC20/extensions/ERC20BurnableUpgradeable.sol";
import { ERC20PermitUpgradeable } from "../../../lib/openzeppelin-contracts-upgradeable/contracts/token/ERC20/extensions/ERC20PermitUpgradeable.sol";
import { SafeERC20 } from "../../../lib/openzeppelin-contracts/contracts/token/ERC20/utils/SafeERC20.sol";
import { Math } from "../../../lib/openzeppelin-contracts/contracts/utils/math/Math.sol";
import { RoycoBase } from "../../base/RoycoBase.sol";
import { IRoycoDayKernel } from "../../interfaces/IRoycoDayKernel.sol";
import { IRoycoVaultTranche } from "../../interfaces/IRoycoVaultTranche.sol";
import { WAD_DECIMALS } from "../../libraries/Constants.sol";
import { AssetClaims, DispatchMode, SyncedAccountingState, TrancheType } from "../../libraries/Types.sol";
import { NAV_UNIT, RoycoUnitsMath, TRANCHE_UNIT, toUint256 } from "../../libraries/Units.sol";
import { AssetLedgerLogic } from "../../libraries/logic/AssetLedgerLogic.sol";
import { DispatchLogic } from "../../libraries/logic/DispatchLogic.sol";
import { ValuationLogic } from "../../libraries/logic/ValuationLogic.sol";

/**
 * @title RoycoVaultTranche
 * @author Ankur Dubey, Shivaansh Kapoor, Tomer Ganor
 * @notice Abstract base contract implementing core vault functionality for Royco tranches (ST, JT, and LPT)
 * @dev Tranches interact with the kernel to execute all operations based on the current holistic state of the Royco market
 */
abstract contract RoycoVaultTranche is IRoycoVaultTranche, RoycoBase, ERC20BurnableUpgradeable, ERC20PermitUpgradeable {
    using Math for uint256;
    using RoycoUnitsMath for uint256;
    using SafeERC20 for IERC20;
    using DispatchLogic for address;

    /// @dev Storage slot for RoycoVaultTrancheState using ERC-7201 pattern
    // keccak256(abi.encode(uint256(keccak256("Royco.storage.RoycoVaultTrancheState")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant _ROYCO_VAULT_TRANCHE_STORAGE_SLOT = 0xb29e56aa3db56637b513fb077b36928988b241f28eccd4f6a5bd34624bbe3900;

    /// @dev Permissions the function to only be callable by the kernel, the single source of truth for sync-driven share mints
    modifier onlyKernel() {
        require(msg.sender == _getRoycoVaultTrancheStorage().kernel, ONLY_KERNEL());
        _;
    }

    /**
     * @notice Initializes the Royco tranche
     * @dev This function initializes parent contracts and the tranche-specific state
     * @param _params Deployment parameters including name, symbol, initial authority, kernel, and asset
     */
    function __RoycoTranche_init(RoycoTrancheInitParams calldata _params) internal onlyInitializing {
        // Ensure that the asset and kernel are not null
        require(_params.asset != address(0) && _params.kernel != address(0), NULL_ADDRESS());

        // Set the tranche's market wiring
        RoycoVaultTrancheState storage $ = _getRoycoVaultTrancheStorage();
        $.kernel = _params.kernel;
        $.asset = _params.asset;

        // Initialize all the parent contracts
        __RoycoBase_init(_params.initialAuthority);
        __ERC20_init_unchained(_params.name, _params.symbol);
        __ERC20Burnable_init();
        __ERC20Permit_init(_params.name);
    }

    // =============================
    // Tranche Deposit and Redeem Functions
    // =============================

    /// @inheritdoc IRoycoVaultTranche
    function deposit(TRANCHE_UNIT _assets, address _receiver) public virtual override(IRoycoVaultTranche) restricted returns (uint256 shares) {
        require(_receiver != address(0), ERC20InvalidReceiver(address(0)));

        // Transfer the assets to the kernel
        RoycoVaultTrancheState storage $ = _getRoycoVaultTrancheStorage();
        IERC20($.asset).safeTransferFrom(msg.sender, $.kernel, toUint256(_assets));

        // Deposit the assets into the Royco market, the kernel prices the shares and mints them to the receiver
        shares = _deposit(DispatchMode.EXECUTE, _assets, _receiver);

        emit Deposit(msg.sender, _receiver, _assets, shares);
    }

    /// @inheritdoc IRoycoVaultTranche
    function redeem(
        uint256 _shares,
        address _receiver,
        address _owner
    )
        public
        virtual
        override(IRoycoVaultTranche)
        restricted
        returns (AssetClaims memory claims)
    {
        require(_receiver != address(0), ERC20InvalidReceiver(address(0)));

        // Spend allowance if msg.sender is not the owner
        if (msg.sender != _owner) _spendAllowance(_owner, msg.sender, _shares);

        // Process the withdrawal from the Royco market, the kernel burns the owner's shares after scaling their claims
        // It is expected that the kernel transfers the assets directly to the receiver
        claims = _redeem(DispatchMode.EXECUTE, _shares, _receiver, _owner);

        emit Redeem(msg.sender, _receiver, claims, _shares);
    }

    // =============================
    // Tranche Max Deposit and Redeem Functions
    // =============================

    /// @inheritdoc IRoycoVaultTranche
    function maxDeposit(address _receiver) external view virtual override(IRoycoVaultTranche) returns (TRANCHE_UNIT assets) {
        return IRoycoDayKernel(kernel()).inkindMaxDeposit(_receiver);
    }

    /// @inheritdoc IRoycoVaultTranche
    function maxRedeem(address _owner) public view virtual override(IRoycoVaultTranche) returns (uint256 shares) {
        // The maximum redeemable shares are the minimum of the owner's share balance and the globally redeemable shares the kernel prices
        return Math.min(balanceOf(_owner), IRoycoDayKernel(kernel()).inkindMaxRedeemable(_owner));
    }

    // =============================
    // Tranche Preview and Conversion Functions
    // =============================

    /// @inheritdoc IRoycoVaultTranche
    /// @dev Routes the deposit through the execute-and-revert pattern so the quote is produced by the actual kernel deposit path under its real semantics
    function previewDeposit(TRANCHE_UNIT _assets) external virtual override(IRoycoVaultTranche) returns (uint256 shares) {
        return _deposit(DispatchMode.SIMULATE, _assets, kernel());
    }

    /// @inheritdoc IRoycoVaultTranche
    /// @dev Routes the redemption through the execute-and-revert pattern so the quote is produced by the actual kernel redemption path under its real semantics
    function previewRedeem(uint256 _shares) external virtual override(IRoycoVaultTranche) returns (AssetClaims memory claims) {
        return _redeem(DispatchMode.SIMULATE, _shares, kernel(), address(0));
    }

    /// @inheritdoc IRoycoVaultTranche
    function convertToAssets(uint256 _shares) public view virtual override(IRoycoVaultTranche) returns (AssetClaims memory claims) {
        // Get the post-sync tranche state: applying NAV reconciliation
        (SyncedAccountingState memory state, AssetClaims memory trancheClaims, uint256 trancheTotalShares) =
            IRoycoDayKernel(kernel()).previewSyncTrancheAccountingFor(TRANCHE_TYPE());
        if (TRANCHE_TYPE() == TrancheType.LIQUIDITY_PROVIDER) {
            // We exclude any idle (not reinvested) ST shares from the LPT claims in order to ensure that its share price does not drop due to slippage incurred on reinvestment
            trancheClaims.stShares = 0;
            trancheClaims.nav = state.lptRawNAV;
        }
        return AssetLedgerLogic._scaleAssetClaims(trancheClaims, _shares, trancheTotalShares, true);
    }

    /// @inheritdoc IRoycoVaultTranche
    function convertToShares(TRANCHE_UNIT _assets) public view virtual override(IRoycoVaultTranche) returns (uint256 shares) {
        address kernel_ = kernel();

        // Value the assets specified in NAV units
        NAV_UNIT value = (TRANCHE_TYPE() == TrancheType.LIQUIDITY_PROVIDER)
            ? IRoycoDayKernel(kernel_).convertLPTAssetsToValue(_assets)
            : IRoycoDayKernel(kernel_).convertCollateralAssetsToValue(_assets);

        // Get the post-sync tranche state
        (SyncedAccountingState memory state, AssetClaims memory trancheClaims, uint256 trancheTotalShares) =
            IRoycoDayKernel(kernel_).previewSyncTrancheAccountingFor(TRANCHE_TYPE());

        // We exclude any idle (not reinvested) ST shares from the LPT NAV basis in order to ensure that its NAV per share does not drop due to slippage incurred on reinvestment
        NAV_UNIT navBasis = ((TRANCHE_TYPE() == TrancheType.LIQUIDITY_PROVIDER) ? state.lptRawNAV : trancheClaims.nav);
        shares = ValuationLogic._convertToShares(value, navBasis, trancheTotalShares, Math.Rounding.Floor);
    }

    // =============================
    // General Tranche View Functions
    // =============================

    /// @inheritdoc IRoycoVaultTranche
    function totalAssets() external view virtual override(IRoycoVaultTranche) returns (AssetClaims memory claims) {
        (, claims,) = IRoycoDayKernel(kernel()).previewSyncTrancheAccountingFor(TRANCHE_TYPE());
    }

    /// @inheritdoc IRoycoVaultTranche
    function asset() external view virtual override(IRoycoVaultTranche) returns (address) {
        return _getRoycoVaultTrancheStorage().asset;
    }

    /// @inheritdoc IRoycoVaultTranche
    function kernel() public view virtual override(IRoycoVaultTranche) returns (address) {
        return _getRoycoVaultTrancheStorage().kernel;
    }

    /**
     * @inheritdoc IERC20Metadata
     * @dev The kernel always uses WAD precision for NAV units
     * @dev Shares are minted using NAV_UNIT values instead of TRANCHE_UNIT values, so they have identical precision to NAV_UNIT values (WAD precision)
     */
    function decimals() public view virtual override(ERC20Upgradeable, IERC20Metadata) returns (uint8) {
        return uint8(WAD_DECIMALS);
    }

    /// @dev Returns the type of the tranche (Senior, Junior, or Liquidity)
    function TRANCHE_TYPE() public pure virtual returns (TrancheType);

    // =============================
    // Kernel Mint and Burn Entrypoints
    // =============================

    /// @inheritdoc IRoycoVaultTranche
    function mintProtocolFeeShares(
        address _protocolFeeRecipient,
        uint256 _protocolFeeShares
    )
        external
        virtual
        override(IRoycoVaultTranche)
        onlyKernel
        returns (uint256 totalTrancheShares)
    {
        // Mint the precomputed protocol fee shares to the recipient (the kernel prices them jointly with the liquidity premium)
        if (_protocolFeeShares != 0) _mint(_protocolFeeRecipient, _protocolFeeShares);

        totalTrancheShares = totalSupply();
        emit ProtocolFeeSharesMinted(_protocolFeeRecipient, _protocolFeeShares, totalTrancheShares);
    }

    /// @inheritdoc IRoycoVaultTranche
    function kernelMint(address _to, uint256 _shares) external virtual override(IRoycoVaultTranche) onlyKernel {
        require(_to != address(0), ERC20InvalidReceiver(address(0)));
        _mint(_to, _shares);
    }

    /// @inheritdoc IRoycoVaultTranche
    function kernelBurn(address _from, uint256 _shares) external virtual override(IRoycoVaultTranche) onlyKernel {
        _burn(_from, _shares);
    }

    // =============================
    // Public Burn Functions
    // =============================

    /// @inheritdoc ERC20BurnableUpgradeable
    function burn(uint256 _shares) public virtual override(ERC20BurnableUpgradeable) restricted {
        super.burn(_shares);
    }

    /// @inheritdoc ERC20BurnableUpgradeable
    function burnFrom(address _account, uint256 _shares) public virtual override(ERC20BurnableUpgradeable) restricted {
        super.burnFrom(_account, _shares);
    }

    // =============================
    // Internal Utility Functions
    // =============================

    /**
     * @dev Deposits the assets into the Royco market through the kernel's in-kind deposit entrypoint
     * @dev The kernel resolves the deposited tranche from this calling tranche, prices the shares at its pre-deposit effective NAV against the post-sync supply, and mints them to the receiver
     * @dev Forwards msg.sender as the caller for an execution, a simulation carries the null synthetic caller so previews never vary by caller
     * @param _mode The dispatch mode: SIMULATE computes the operation and unwinds every mutation by reverting with its result, EXECUTE settles it
     * @param _assets The amount of assets to deposit, denominated in the tranche's base asset units
     * @param _receiver The address that receives the minted shares
     * @return shares The number of shares minted for the deposit
     */
    function _deposit(DispatchMode _mode, TRANCHE_UNIT _assets, address _receiver) internal virtual returns (uint256 shares) {
        // Deposit the assets into the Royco market through the kernel's in-kind deposit entrypoint, which prices and mints the shares
        // The kernel rejects a deposit that prices to zero shares
        return abi.decode(
            kernel()._dispatchAndUnwrap(_mode, abi.encodeCall(IRoycoDayKernel.inkindDeposit, (_mode, _assets, _resolveCaller(_mode), _receiver))), (uint256)
        );
    }

    /**
     * @dev Redeems the shares from the Royco market through the kernel's in-kind redemption entrypoint
     * @dev The kernel resolves the redeemed tranche from this calling tranche, transfers the redeemed assets directly to the receiver, and burns the owner's shares after scaling their claims
     * @dev Forwards msg.sender as the caller for an execution, a simulation carries the null synthetic caller so previews never vary by caller
     * @param _mode The dispatch mode: SIMULATE computes the operation and unwinds every mutation by reverting with its result, EXECUTE settles it
     * @param _shares The number of shares to redeem
     * @param _receiver The address that receives the redeemed assets
     * @param _owner The address whose shares are burned for the redemption
     * @return claims The distribution of assets transferred to the receiver on redemption
     */
    function _redeem(DispatchMode _mode, uint256 _shares, address _receiver, address _owner) internal virtual returns (AssetClaims memory claims) {
        // Redeem the shares through the kernel's in-kind redemption entrypoint, the kernel transfers the redeemed assets directly to the receiver
        // The kernel rejects a zero-share redemption
        return abi.decode(
            kernel()._dispatchAndUnwrap(_mode, abi.encodeCall(IRoycoDayKernel.inkindRedeem, (_mode, _shares, _resolveCaller(_mode), _owner, _receiver))),
            (AssetClaims)
        );
    }

    /// @dev Resolves the caller forwarded to the kernel: an execution forwards msg.sender and a simulation carries the null address so previews never vary by caller
    /// @param _mode The dispatch mode used to resolve the caller
    function _resolveCaller(DispatchMode _mode) internal view returns (address) {
        return (_mode == DispatchMode.SIMULATE) ? address(0) : msg.sender;
    }

    /**
     * @inheritdoc ERC20Upgradeable
     * @dev Routes every balance update through the kernel's screening hook, which enforces the market's blacklist and
     *      reverts when the kernel is paused: transfers, mints, and burns are all gated by the kernel
     */
    function _update(address _from, address _to, uint256 _value) internal override(ERC20Upgradeable) {
        // Call the kernel's pre-balance update hook to assert that the balance update is valid
        IRoycoDayKernel(kernel()).preTrancheBalanceUpdateHook(msg.sender, _from, _to, _value);

        // Call the parent contract's update function to update the balance
        ERC20Upgradeable._update(_from, _to, _value);
    }

    /**
     * @notice Returns a storage pointer to the RoycoVaultTrancheState storage
     * @dev Uses ERC-7201 storage slot pattern for collision-resistant storage
     * @return $ Storage pointer to the tranche's state
     */
    function _getRoycoVaultTrancheStorage() internal pure returns (RoycoVaultTrancheState storage $) {
        assembly ("memory-safe") {
            $.slot := _ROYCO_VAULT_TRANCHE_STORAGE_SLOT
        }
    }
}

