// SPDX-License-Identifier: LicenseRef-PolyForm-Perimeter-1.0.1
pragma solidity ^0.8.28;

import { IERC20 } from "../../../lib/openzeppelin-contracts/contracts/token/ERC20/IERC20.sol";
import { IRoycoDayKernel } from "../../interfaces/IRoycoDayKernel.sol";
import { IRoycoSeniorTranche } from "../../interfaces/IRoycoSeniorTranche.sol";
import { IRoycoVaultTranche } from "../../interfaces/IRoycoVaultTranche.sol";
import { Cache, CacheKey } from "../Cache.sol";
import { ZERO_NAV_UNITS } from "../Constants.sol";
import { SyncedAccountingState } from "../Types.sol";
import { Math, NAV_UNIT, toUint256 } from "../Units.sol";
import { ValuationLogic } from "./ValuationLogic.sol";

/**
 * @title FeeAndLiquidityPremiumLogic
 * @author Shivaansh Kapoor, Ankur Dubey, Tomer Ganor
 * @notice The post-sync protocol fee and liquidity-premium share mint for a Royco market: the premium/fee split and the mint orchestration
 */
library FeeAndLiquidityPremiumLogic {
    /**
     * @notice Mints the protocol fee shares and the liquidity premium shares accrued by a pre-op sync
     * @dev The liquidity premium is senior yield routed to the LPT: it is minted as senior tranche shares the kernel holds for the
     *      liquidity provider tranche, leaving the collateral NAV (and thus coverage) unchanged, so the mint is coverage-neutral
     * @dev The premium and ST protocol fee are priced jointly against the pre-sync senior supply, so neither dilutes the other
     * @dev The LPT protocol fee is carved out of the liquidity premium and remitted as senior shares to the protocol, so the LPT receives the premium net of the fee and no LPT shares are minted
     * @dev The minted premium accumulates as idle senior shares and are not reinvested here
     * @param $ The storage state of the Royco Kernel that is delegatecalling into this function
     * @param _state The synced accounting state whose accrued liquidity premium and protocol fees are minted
     */
    function _processFeesAndLiquidityPremium(IRoycoDayKernel.RoycoDayKernelState storage $, SyncedAccountingState memory _state) internal {
        address protocolFeeRecipient = $.protocolFeeRecipient;
        address seniorTranche = $.seniorTranche;

        // Split the senior effective NAV into its two senior-share carve-outs (the liquidity premium net of the LPT protocol fee, and the ST protocol fee plus that carved-out LPT fee)
        // at one joint price against the pre-sync senior supply, so neither carve-out dilutes the other
        (uint256 liquidityPremiumShares, uint256 stProtocolFeeShares, uint256 stTotalSupplyAfterMints) =
            _computeSTFeeAndLiquidityPremiumSharesToMint(_state, IERC20(seniorTranche).totalSupply());

        // Cache the senior share price at this sync's post-mint value before any venue mark read consumes it
        Cache._write(CacheKey.ST_SHARE_PRICE, toUint256(ValuationLogic._computeTrancheShareRate(stTotalSupplyAfterMints, _state.stEffectiveNAV)));

        // Mint the senior protocol fee shares (the ST protocol fee plus the LPT protocol fee carved out of the premium) to the protocol fee recipient, priced identically to the premium shares minted above
        if (stProtocolFeeShares != 0) {
            IRoycoVaultTranche(seniorTranche).mintProtocolFeeShares(protocolFeeRecipient, stProtocolFeeShares);
        }
        // If JT fees were accrued, price them against the post-fee junior NAV (the fee dilutes existing holders) and mint to the recipient
        if (_state.jtProtocolFee != ZERO_NAV_UNITS) {
            address juniorTranche = $.juniorTranche;
            uint256 jtProtocolFeeShares = ValuationLogic._convertToShares(
                _state.jtProtocolFee, (_state.jtEffectiveNAV - _state.jtProtocolFee), IERC20(juniorTranche).totalSupply(), Math.Rounding.Floor
            );
            IRoycoVaultTranche(juniorTranche).mintProtocolFeeShares(protocolFeeRecipient, jtProtocolFeeShares);
        }
        // Mint the liquidity premium as senior tranche shares held by the kernel on behalf of the liquidity provider tranche
        // The premium is already booked into the senior effective NAV, so minting these shares only reassigns senior appreciation to the LPT
        // The minted shares stay idle here, the operation post-op sync deploys the accumulated pile once the operation has settled
        if (liquidityPremiumShares != 0) {
            IRoycoSeniorTranche(seniorTranche).mintLiquidityPremiumShares(liquidityPremiumShares);
            $.lptOwnedSeniorTrancheShares += liquidityPremiumShares;
        }
    }

    /**
     * @notice Computes the senior tranche shares minted for this sync's senior yield split: the LPT liquidity premium net of the LPT protocol fee, and the ST protocol fee plus that carved-out LPT fee
     * @dev Both the premium and the fee are reallocations of value already booked into the senior effective NAV (no assets enter or
     *      leave), so minting them is NAV-neutral and coverage-neutral: the premium reassigns senior appreciation to the LPT and the fee to the protocol
     * @dev Both are priced over the same pre-sync supply against one shared denominator, the NAV the pre-existing shares retain net of the premium and fee, so neither dilutes the other
     * @param _state The synced accounting state carrying the senior effective NAV, the liquidity premium, and the ST protocol fee
     * @param _stTotalSupply The total senior tranche share supply before this sync mints the premium and fee shares
     * @return liquidityPremiumShares The senior shares to mint as the LPT liquidity premium net of the LPT protocol fee, rounded down
     * @return stProtocolFeeShares The senior shares to mint as the ST protocol fee plus the LPT protocol fee carved out of the premium, rounded down
     * @return stTotalSupplyAfterMints The total senior tranche supply after minting the premium and fee shares
     */
    function _computeSTFeeAndLiquidityPremiumSharesToMint(
        SyncedAccountingState memory _state,
        uint256 _stTotalSupply
    )
        internal
        pure
        returns (uint256 liquidityPremiumShares, uint256 stProtocolFeeShares, uint256 stTotalSupplyAfterMints)
    {
        // The pre-existing senior shares retain the senior effective NAV net of the premium and fee
        // NOTE: The waterfall enforces that the ST effective NAV is inclusive of the LPT premium and ST fees, so the subtraction never underflows
        NAV_UNIT retainedSeniorNAV = (_state.stEffectiveNAV - _state.lptLiquidityPremium - _state.stProtocolFee);

        // Convert each carve-out into senior shares against the retained NAV over the pre-sync supply (the zero-NAV boundary is handled in _convertToShares)
        // The LPT protocol fee is levied on the liquidity premium and remitted as senior shares to the protocol, so it moves from the LPT premium carve-out into the protocol fee carve-out
        // lptProtocolFee <= lptLiquidityPremium always (the accountant floors the fee as a fraction of the premium at a rate at most WAD), so the premium net of the fee never underflows
        liquidityPremiumShares =
            ValuationLogic._convertToShares((_state.lptLiquidityPremium - _state.lptProtocolFee), retainedSeniorNAV, _stTotalSupply, Math.Rounding.Floor);
        stProtocolFeeShares =
            ValuationLogic._convertToShares((_state.stProtocolFee + _state.lptProtocolFee), retainedSeniorNAV, _stTotalSupply, Math.Rounding.Floor);
        stTotalSupplyAfterMints = (_stTotalSupply + liquidityPremiumShares + stProtocolFeeShares);
    }
}

src/libraries/logic/ValuationLogic.sol.content:
// SPDX-License-Identifier: LicenseRef-PolyForm-Perimeter-1.0.1
pragma solidity ^0.8.28;

import { IRoycoDayKernel } from "../../interfaces/IRoycoDayKernel.sol";
import { MAX_MINT_DILUTION_WAD, VIRTUAL_SHARES, VIRTUAL_VALUE, WAD, ZERO_NAV_UNITS, ZERO_TRANCHE_UNITS } from "../Constants.sol";
import { Math, NAV_UNIT, RoycoUnitsMath, TRANCHE_UNIT, toUint256 } from "../Units.sol";

/**
 * @title ValuationLogic
 * @author Shivaansh Kapoor, Ankur Dubey, Tomer Ganor
 * @notice Tranche NAV valuation for a Royco market: the collateral and LPT raw NAV reads, the LPT effective NAV, and NAV-to-shares conversion
 * @dev Invoked by the kernel via delegatecall
 */
library ValuationLogic {
    using RoycoUnitsMath for NAV_UNIT;
    using RoycoUnitsMath for uint256;
    using Math for uint256;

    /**
     * @notice Returns the mark-to-market value of the coinvested collateral backing the senior and junior tranches, denominated in the NAV units (USD, BTC, etc.) for this kernel
     * @param $ The storage state of the Royco Kernel that is delegatecalling into this function
     * @return collateralNAV The pure value of the held collateral assets
     */
    function _getCollateralNAV(IRoycoDayKernel.RoycoDayKernelState storage $) internal view returns (NAV_UNIT collateralNAV) {
        // With no holdings there is nothing to price
        TRANCHE_UNIT totalCollateralAssets = $.totalCollateralAssets;
        if (totalCollateralAssets == ZERO_TRANCHE_UNITS) return ZERO_NAV_UNITS;
        // Get the held collateral assets and convert them to NAV units via the kernel's pricing
        return IRoycoDayKernel(address(this)).convertCollateralAssetsToValue(totalCollateralAssets);
    }

    /**
     * @notice Returns the raw net asset value of the liquidity provider tranche denominated in the NAV units (USD, BTC, etc.) for this kernel
     * @param $ The storage state of the Royco Kernel that is delegatecalling into this function
     * @return lptRawNAV The pure net asset value of the liquidity provider tranche invested assets
     */
    function _getLiquidityProviderTrancheRawNAV(IRoycoDayKernel.RoycoDayKernelState storage $) internal view returns (NAV_UNIT lptRawNAV) {
        // With no holdings there is nothing to price, an uninitialized venue is never queried
        TRANCHE_UNIT totalLPTAssets = $.totalLPTAssets;
        if (totalLPTAssets == ZERO_TRANCHE_UNITS) return ZERO_NAV_UNITS;
        // Get the yield bearing assets owned by LPT and convert them to NAV units via the kernel's pricing
        return IRoycoDayKernel(address(this)).convertLPTAssetsToValue(totalLPTAssets);
    }

    /**
     * @notice Returns the effective net asset value (NAV) of the liquidity provider tranche denominated in the NAV units (USD, BTC, etc.) for this kernel
     * @dev The effective NAV is the liquidity provider tranche's deployed market-making inventory (its raw NAV) plus the value of the
     *      senior tranche shares it holds from accumulated, not yet reinvested, liquidity premium payments
     * @dev Reads the held senior-share count from storage, the value execution sees after the premium mint
     *      The preview path uses the overload below to inject the post-mint count that storage does not yet reflect
     * @dev The senior NAV and share supply must be mutually consistent: the post-sync effective NAV against the
     *      post-carve-out-mint total supply, so the held senior shares are valued at the correct NAV per share
     * @param $ The storage state of the Royco Kernel that is delegatecalling into this function
     * @param _stEffectiveNAV The senior tranche's post-sync effective NAV: the total NAV backing all senior shares after reconciling unrealized PnL
     * @param _totalSeniorTrancheShares The total senior tranche shares outstanding after minting the premium and protocol fee shares
     * @return lptEffectiveNAV The effective net asset value of the liquidity provider tranche
     */
    function _getLiquidityProviderTrancheEffectiveNAV(
        IRoycoDayKernel.RoycoDayKernelState storage $,
        NAV_UNIT _stEffectiveNAV,
        uint256 _totalSeniorTrancheShares
    )
        internal
        view
        returns (NAV_UNIT lptEffectiveNAV)
    {
        // Value the held senior shares using the count committed to storage (the value execution sees after the premium mint)
        return _getLiquidityProviderTrancheEffectiveNAV($, _stEffectiveNAV, _totalSeniorTrancheShares, $.lptOwnedSeniorTrancheShares);
    }

    /**
     * @notice Returns the effective net asset value of the liquidity provider tranche for an explicitly supplied held senior-share count
     * @dev The preview path supplies the post-mint held-share count (current storage plus this sync's premium shares) before the
     *      premium mint commits it to storage, so the previewed LPT effective NAV matches the value execution computes from storage
     * @param $ The storage state of the Royco Kernel that is delegatecalling into this function
     * @param _stEffectiveNAV The senior tranche's post-sync effective NAV: the total NAV backing all senior shares after reconciling unrealized PnL
     * @param _totalSeniorTrancheShares The total senior tranche shares outstanding after minting the premium and protocol fee shares
     * @param _lptOwnedSeniorTrancheShares The senior tranche shares held by the liquidity provider tranche from accumulated liquidity premium payments
     * @return lptEffectiveNAV The effective net asset value of the liquidity provider tranche
     */
    function _getLiquidityProviderTrancheEffectiveNAV(
        IRoycoDayKernel.RoycoDayKernelState storage $,
        NAV_UNIT _stEffectiveNAV,
        uint256 _totalSeniorTrancheShares,
        uint256 _lptOwnedSeniorTrancheShares
    )
        internal
        view
        returns (NAV_UNIT lptEffectiveNAV)
    {
        // Get the value of LPT's market-making inventory
        NAV_UNIT lptRawNAV = _getLiquidityProviderTrancheRawNAV($);

        // If there are no held senior shares or no senior shares outstanding, the effective NAV is just the raw NAV
        if (_lptOwnedSeniorTrancheShares == 0 || _totalSeniorTrancheShares == 0) return lptRawNAV;

        // The LPT effective NAV is the sum of the NAVs of its market-making inventory and its held ST shares
        return (lptRawNAV + _convertToValue(_lptOwnedSeniorTrancheShares, _totalSeniorTrancheShares, _stEffectiveNAV, Math.Rounding.Floor));
    }

    /**
     * @notice Returns the number of shares that have a claim on the specified value, clamped by the protocol's max mint dilution
     * @dev The mint-sizing share conversion, shared by the tranches and the kernel-side mint sizing so both resolve identical share counts
     * @dev See _convertToSharesUnclamped for the clamp-free variant, used only as a valuation reference and never to size a real mint
     * @dev The mint-dilution clamp caps the share of the post-mint supply a single mint can own, bounding the share count any one mint can create
     * @dev The clamp arms only in the collapsed-price regime where fair pricing itself mints runaway share counts, the state a
     *      supply-inflation attack needs, so a mint into a healthily priced tranche always prices fairly
     * @dev With no shares outstanding the conversion stays 1:1 (a bootstrap mint dilutes nobody, so the clamp is exempt)
     * @param _value The value to convert in NAV units
     * @param _totalValue The total tranche controlled value in NAV units
     * @param _totalSupply The total supply of tranche shares (including any marginally minted fee shares)
     * @param _rounding The rounding mode to use for whichever branch sizes the mint
     * @return shares The number of shares that have a claim on the specified value
     */
    function _convertToShares(NAV_UNIT _value, NAV_UNIT _totalValue, uint256 _totalSupply, Math.Rounding _rounding) internal pure returns (uint256 shares) {
        // The effective supply is the total supply plus the virtual shares
        uint256 effectiveSupply = (_totalSupply + VIRTUAL_SHARES);
        NAV_UNIT denominator = (_totalValue + VIRTUAL_VALUE);
        // Arm the clamp only in the collapsed-price regime where fair pricing itself mints massive share counts
        uint256 clampedShares = type(uint256).max;
        if (effectiveSupply.mulDiv((WAD - MAX_MINT_DILUTION_WAD), MAX_MINT_DILUTION_WAD, Math.Rounding.Ceil) > toUint256(denominator)) {
            // Cap the mint at the max share of the post-mint effective supply a single mint may own
            clampedShares = effectiveSupply.mulDiv(MAX_MINT_DILUTION_WAD, (WAD - MAX_MINT_DILUTION_WAD), _rounding);
        }
        // Below the cap the mint takes the fair, unclamped virtual-shares price
        return Math.min(clampedShares, _convertToSharesUnclamped(_value, _totalValue, _totalSupply, _rounding));
    }

    /**
     * @notice Returns the shares that have a claim on the specified value under fair (unclamped) virtual-shares pricing
     * @dev Identical to _convertToShares but WITHOUT the mint-dilution clamp
     * @param _value The value to convert in NAV units
     * @param _totalValue The total tranche controlled value in NAV units
     * @param _totalSupply The total supply of tranche shares
     * @param _rounding The rounding mode to use
     * @return shares The number of shares that have a claim on the specified value at the fair, unclamped price
     */
    function _convertToSharesUnclamped(
        NAV_UNIT _value,
        NAV_UNIT _totalValue,
        uint256 _totalSupply,
        Math.Rounding _rounding
    )
        internal
        pure
        returns (uint256 shares)
    {
        // The fair virtual-shares price, matching _convertToShares' unclamped branch
        return (_totalSupply + VIRTUAL_SHARES).mulDiv(_value, (_totalValue + VIRTUAL_VALUE), _rounding);
    }

    /**
     * @notice Returns the value (in NAV units) that the specified amount of shares have a claim on
     * @dev The single value-conversion primitive, the inverse of _convertToShares, so a share count and its value round-trip consistently
     * @param _shares The number of shares to convert
     * @param _totalSupply The total supply of tranche shares (including any marginally minted fee shares)
     * @param _totalValue The total tranche controlled value in NAV units
     * @param _rounding The rounding mode to use
     * @return value The value in NAV units that the shares have a claim on
     */
    function _convertToValue(uint256 _shares, uint256 _totalSupply, NAV_UNIT _totalValue, Math.Rounding _rounding) internal pure returns (NAV_UNIT value) {
        return (_totalValue + VIRTUAL_VALUE).mulDiv(_shares, (_totalSupply + VIRTUAL_SHARES), _rounding);
    }

    /**
     * @notice Returns a tranche share rate: the NAV-unit value of one whole tranche share at the given tranche's total share supply and effective NAV
     * @param _trancheTotalSupply The total tranche share supply the rate is computed against (for the senior tranche, the post-mint supply)
     * @param _trancheEffectiveNAV The tranche's effective NAV backing all of its shares
     * @return rate The NAV-unit value of one whole tranche share, rounded down
     */
    function _computeTrancheShareRate(uint256 _trancheTotalSupply, NAV_UNIT _trancheEffectiveNAV) internal pure returns (NAV_UNIT rate) {
        return _convertToValue(WAD, _trancheTotalSupply, _trancheEffectiveNAV, Math.Rounding.Floor);
    }
}

